  const totals = invoiceTotals(invoice);
  // Line total: 2940, VAT: 2940 * 21 / 100 = 617.4 → 617
  assert.equal(totals.subtotal, 2940);
  assert.equal(totals.vat, 617);
  assert.equal(totals.total, 3557);
});

test('invoiceTotals: multiple discounts', () => {
  const invoice = {
    lines: [
      { qty: 8, unitPrice: 9500, discountPercent: 10, vatRate: 21 },
      { qty: 5, unitPrice: 8500, discountPercent: 0, vatRate: 21 },
      { qty: 1, unitPrice: 60000, discountPercent: 20, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Dev: 76000 - 7600 = 68400, VAT = 14364
  // Des: 42500, VAT = 8925
  // Workshop: 60000 - 12000 = 48000, VAT = 10080
  // Subtotal: 178500, Discount: 19600, VAT: 33369
  // Total: 178500 - 19600 + 33369 = 192269
  assert.equal(totals.subtotal, 178500);
  assert.equal(totals.discount, 19600);
  assert.equal(totals.vat, 33369);
  assert.equal(totals.total, 192269);
});

test('invoiceTotals: decimal discounts', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 2.5, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line total: 10000, Discount: 10000 * 2.5 / 100 = 250
  // Bulk discount (10+ units): 9750 * 2.5 / 100 = 244 (rounded)
  // Total discount: 250 + 244 = 494
  // Discounted: 10000 - 494 = 9506, VAT: 9506 * 21 / 100 = 1996 (rounded)
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 494);
  assert.equal(totals.vat, 1996);
  assert.equal(totals.total, 11502);
});

test('invoiceTotals: bulk discount with 10 units', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line total: 10000, No line discount
  // Bulk discount (10+ units): 10000 * 2.5 / 100 = 250
  // Discounted: 9750, VAT: 9750 * 21 / 100 = 2047.5 → 2048
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 250);
  assert.equal(totals.vat, 2048);
  assert.equal(totals.total, 11798);
});

test('invoiceTotals: no bulk discount with 9 units', () => {
  const invoice = {
    lines: [
      { qty: 9, unitPrice: 1000, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line total: 9000, No discounts
  // Discounted: 9000, VAT: 9000 * 21 / 100 = 1890
  assert.equal(totals.subtotal, 9000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 1890);
  assert.equal(totals.total, 10890);
});

test('invoiceTotals: bulk discount with line discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line total: 10000
  // Line discount: 10000 * 10 / 100 = 1000
  // After line discount: 9000
  // Bulk discount: 9000 * 2.5 / 100 = 225
  // Total discount: 1000 + 225 = 1225
  // Discounted: 8775, VAT: 8775 * 21 / 100 = 1842.75 → 1843
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 1225);
  assert.equal(totals.vat, 1843);
  assert.equal(totals.total, 10618);
});

test('invoiceTotals: bulk discount applied to smallest unit first', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 100, vatRate: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line total: 1000
  // Bulk discount: 1000 * 2.5 / 100 = 25
  assert.equal(totals.subtotal, 1000);
  assert.equal(totals.discount, 25);
  assert.equal(totals.total, 975);
});

test('invoiceTotals: bulk discount on large quantity', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 9500, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line total: 950000
  // Bulk discount: 950000 * 2.5 / 100 = 23750
  // Discounted: 926250, VAT: 926250 * 21 / 100 = 194512.5 → 194512 (banker's rounding)
  assert.equal(totals.subtotal, 950000);
  assert.equal(totals.discount, 23750);
  assert.equal(totals.vat, 194512);
  assert.equal(totals.total, 1120762);
});

test('invoiceTotals: bulk discount with multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, vatRate: 21 },
      { qty: 5, unitPrice: 2000, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line 1: 10000, bulk discount 250, discounted 9750, VAT 2048
  // Line 2: 10000, no bulk discount (qty=5), discounted 10000, VAT 2100
  // Total discount: 250
  // Total: 20000 - 250 + 4148 = 23898
  assert.equal(totals.subtotal, 20000);
  assert.equal(totals.discount, 250);
  assert.equal(totals.vat, 4148);
  assert.equal(totals.total, 23898);
});

test('invoiceTotals: bulk discount with line discount and voucher', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
    ],
    voucher: { code: 'TEST', amount: 500 },
  };

  const totals = invoiceTotals(invoice);
  // Line total: 10000
  // Line discount: 1000
  // Bulk discount: 225
  // Total discount: 1225
  // Discounted: 8775, VAT: 1843
  // Voucher: 500
  // Total: 10000 - 1225 + 1843 - 500 = 10118
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 1225);
  assert.equal(totals.vat, 1843);
  assert.equal(totals.voucher, 500);
  assert.equal(totals.total, 10118);
});

test('invoiceTotals: bulk discount rounding', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 333, vatRate: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line total: 3330
  // Bulk discount: 3330 * 2.5 / 100 = 83.25 → 83
  assert.equal(totals.subtotal, 3330);
  assert.equal(totals.discount, 83);
  assert.equal(totals.total, 3247);
});

test('invoiceTotals: bulk discount exactly at threshold', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 500, vatRate: 9 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line total: 5000
  // Bulk discount: 5000 * 2.5 / 100 = 125
  // Discounted: 4875, VAT: 4875 * 9 / 100 = 438.75 → 439
  assert.equal(totals.subtotal, 5000);
  assert.equal(totals.discount, 125);
  assert.equal(totals.vat, 439);
  assert.equal(totals.total, 5314);
});

