test('invoiceTotals: VAT with different VAT rates', () => {
  // DEV-HOUR: 21% VAT, PRINT-A4: 9% VAT
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1, discountPercent: 0 },
      { sku: 'PRINT-A4', qty: 10, discountPercent: 0 },
    ],
  });

  assert.ok(result.ok);
  const totals = invoiceTotals(result.value);
  // Dev: 9500 * 21 / 100 = 1995
  // Print: 10 * 37 = 370, 370 * 9 / 100 = 33.3 -> rounds to 33
  const printVat = Math.round(370 * 9 / 100);
  assert.equal(totals.subtotal, 9500 + 370);
  assert.equal(totals.vat, 1995 + printVat);
  assert.equal(totals.total, 9500 + 370 + 1995 + printVat);
});

