test('lineTotal: single quantity', () => {
  const line = { qty: 1, unitPrice: 9500 };
  assert.equal(lineTotal(line), 9500);
});

test('lineTotal: multiple quantity', () => {
  const line = { qty: 5, unitPrice: 9500 };
  assert.equal(lineTotal(line), 47500);
});

test('lineTotal: large amounts', () => {
