test('invoiceTotals: single line', () => {
  const invoice = {
    lines: [{ qty: 8, unitPrice: 9500, vatRate: 21 }],
  };
  const result = invoiceTotals(invoice);
  // Line total: 76000, VAT 21% = 15960
  assert.equal(result.subtotal, 76000);
  assert.equal(result.vat, 15960);
  assert.equal(result.total, 91960);
});

test('invoiceTotals: multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500, vatRate: 21 },
      { qty: 10, unitPrice: 9500, vatRate: 21 },
      { qty: 1, unitPrice: 120000, vatRate: 21 },
    ],
  };
  const result = invoiceTotals(invoice);
  // 42500 * 21 / 100 = 8925, 95000 * 21 / 100 = 19950, 120000 * 21 / 100 = 25200
  // VAT total: 54075
  assert.equal(result.subtotal, 42500 + 95000 + 120000);
  assert.equal(result.vat, 54075);
  assert.equal(result.total, 257500 + 54075);
});

test('invoiceTotals: empty lines', () => {
  const invoice = { lines: [] };
  const result = invoiceTotals(invoice);
  assert.equal(result.subtotal, 0);
  assert.equal(result.total, 0);
});

test('invoiceTotals: subtotal with discount and VAT', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 6000, vatRate: 21 },
      { qty: 3, unitPrice: 7250, vatRate: 21 },
    ],
  };
  const result = invoiceTotals(invoice);
  // Subtotal: 12000 + 21750 = 33750
  // VAT: 12000 * 0.21 + 21750 * 0.21 = 2520 + 4567.5 = 7087.5 -> rounds to 7088 or 7087
  // Total should include both subtotal and VAT (but no discount)
  assert.equal(result.subtotal, 33750);
  assert.ok(result.total > result.subtotal);
});

test('invoiceTotals: does not mutate invoice', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 9500, vatRate: 21 }],
