    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });

  assert.ok(result.ok);
  const invoice = result.value;

  const addResult = addLine(invoice, { sku: 'DES-HOUR', qty: 5 });
  assert.ok(addResult.ok);
  assert.equal(addResult.value.lines.length, 2);
  assert.equal(addResult.value.lines[1].sku, 'DES-HOUR');
