  const devVat = Math.round(42750 * 21 / 100);
  const desVat = Math.round(25500 * 21 / 100);
  assert.equal(totals.vat, devVat + desVat);
  assert.equal(totals.total, 47500 + 25500 + 60000 - 4750 + devVat + desVat);
});

