});

test('invoiceTotals: with actual invoice from createInvoice', () => {
  // C-002 is standard tier (no automatic discount)
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 8 },
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });

  assert.ok(result.ok);
  const totals = invoiceTotals(result.value);
  const subtotal = 8 * 9500 + 5 * 8500;
  // VAT: 76000 * 0.21 + 42500 * 0.21 = 15960 + 8925 = 24885
  const vat = 15960 + 8925;
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, subtotal + vat);
});

