test('invoiceTotals: VAT on line with discount', () => {
  // DEV-HOUR has 21% VAT, unit price 9500
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });

  assert.ok(result.ok);
  const totals = invoiceTotals(result.value);
  // Line total: 10 * 9500 = 95000
  // Line discount: 95000 * 10 / 100 = 9500
  // Bulk discount: (95000 - 9500) * 2.5 / 100 = 2138
  // Total discount: 9500 + 2138 = 11638
  // Discounted amount: 95000 - 11638 = 83362
  // VAT: 83362 * 21 / 100 = 17506
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 11638);
  assert.equal(totals.vat, 17506);
  assert.equal(totals.total, 100868);
});

