test('invoiceTotals: VAT with different VAT rates', () => {
  // DEV-HOUR: 21% VAT, PRINT-A4: 9% VAT
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1, discountPercent: 0 },
      { sku: 'PRINT-A4', qty: 10, discountPercent: 0 },
    ],
  });

  assert.ok(result.ok);
  const totals = invoiceTotals(result.value);
  // Dev: 9500, no bulk discount (qty<10), VAT 21% = 1995
  // Print: 10 * 37 = 370, bulk discount 9 (qty>=10), discounted 361, VAT 9% = 32
  const devVat = 1995;
  const printVat = Math.round(361 * 9 / 100);
  assert.equal(totals.subtotal, 9500 + 370);
  assert.equal(totals.discount, 9); // bulk discount on Print line only
  assert.equal(totals.vat, devVat + printVat);
  assert.equal(totals.total, 9500 + 370 - 9 + devVat + printVat);
});

